// Command api serves the todo HTTP API. The wiring itself is generated by
// Wire (wire.go -> wire_gen.go); main only picks which graph to build.
package main

import (
	"context"
	"fmt"
	"os"
	"os/signal"
	"syscall"

	"github.com/gin-gonic/gin"
	"github.com/rs/zerolog"

	"example.com/todo/level06/internal/config"
	"example.com/todo/level06/internal/infrastructure/logger"
	"example.com/todo/level06/internal/infrastructure/server"
)

func main() {
	log := logger.New(os.Stdout)
	if err := run(log); err != nil {
		log.Fatal().Err(err).Msg("stopped")
	}
}

func run(log zerolog.Logger) error {
	cfg, err := config.Load()
	if err != nil {
		return err
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	router, cleanup, err := newRouter(ctx, cfg, log)
	if err != nil {
		return err
	}
	defer cleanup()
	log.Info().Str("driver", cfg.DBDriver).Msg("storage ready")

	return server.Run(ctx, cfg.HTTPAddr, router, log)
}

// newRouter is where the runtime DB_DRIVER meets the compile-time Wire graphs:
// it calls the generated injector for the chosen storage.
func newRouter(ctx context.Context, cfg config.Config, log zerolog.Logger) (*gin.Engine, func(), error) {
	switch cfg.DBDriver {
	case config.DriverPostgres:
		return initPostgresApp(ctx, cfg, log)
	case config.DriverMongo:
		return initMongoApp(ctx, cfg, log)
	default:
		return nil, nil, fmt.Errorf("unknown DB_DRIVER %q", cfg.DBDriver)
	}
}
